pub fn leading_trailing(ch: char) -> (u8, u8) {
    let codepoint = ch as u32;
    let index = PROPERTIES.partition_point(|&(start, _, _, _)| start <= codepoint);
    if index > 0 && codepoint <= PROPERTIES[index - 1].1 {
        (PROPERTIES[index - 1].2, PROPERTIES[index - 1].3)
    } else {
        (0, 0)
    }
}
